/**
 * Test dataset definitions for E2E tests.
 *
 * This module defines the source metadata (dimensions, EXIF tags, and assertion parameters)
 * for all synthetic test images generated by `e2e/dataset-gen.ts`.
 *
 * Structure:
 *   - PRIMARY_DATASET: Timeline photos, nested directories, archive folders, and local media.
 *   - GEO_DATASET: 100 geo-tagged photos grouped across 11 cities/regions worldwide.
 *   - DATASET: Consolidated dataset map keyed by relative path (e.g. 'primary/Photos/...').
 */

export interface IDatasetExif {
  DateTimeOriginal?: string;
  GPSLatitude?: number;
  GPSLongitude?: number;
  [key: string]: unknown;
}

export interface IDatasetParams {
  place?: string;
  city?: string;
  [key: string]: unknown;
}

export interface IDatasetEntry {
  size: number[]; // [width, height]
  exif: IDatasetExif;
  params?: IDatasetParams;
}

export type IDatasetMap = Record<string, IDatasetEntry>;

